<script setup lang="ts">
import type { MappingSuggestion,TemplateColumn,RawField } from '../../types'
defineProps<{suggestions:MappingSuggestion[];columns:TemplateColumn[];rawFields:RawField[]}>();defineEmits<{update:[id:string,patch:Partial<MappingSuggestion>]}>()
</script>
<template><div class="table-scroll"><table><thead><tr><th>原始字段 / 样例</th><th>AI 推荐 / 人工目标</th><th>置信度</th><th>推荐解释</th><th>状态与操作</th></tr></thead><tbody><tr v-for="m in suggestions" :key="m.id" :class="{'pending-row':(m.confidence<.8||m.needConfirm)&&m.status==='auto'}"><td><strong class="mono">{{m.rawField}}</strong><small>{{rawFields.find(f=>f.name===m.rawField)?.alias}} · {{rawFields.find(f=>f.name===m.rawField)?.sample??'空值'}}</small></td><td><small>推荐：{{columns.find(c=>c.key===m.recommendedTarget)?.header || '无'}}</small><select :aria-label="`${m.rawField}目标字段`" :value="m.selectedTarget || m.recommendedTarget || ''" @change="$emit('update',m.id,{selectedTarget:($event.target as HTMLSelectElement).value||null,status:'auto',needConfirm:true})"><option value="">请选择目标</option><option v-for="c in columns" :key="c.key" :value="c.key">{{c.header}}</option></select></td><td><strong :class="m.confidence<.8?'text-warn':''">{{Math.round(m.confidence*100)}}%</strong><div class="confidence-track"><div :style="{width:`${m.confidence*100}%`}"></div></div></td><td class="wrap">{{m.reason}}</td><td><span class="badge" :class="m.status==='confirmed'?'success':m.status==='rejected'?'neutral':'warn'">{{{auto:'待审核 / 推荐',confirmed:'已确认',rejected:'已拒绝'}[m.status]}}</span><div class="button-row"><button class="text-button" @click="$emit('update',m.id,{selectedTarget:m.selectedTarget||m.recommendedTarget,status:'confirmed'})">确认</button><button class="text-button" @click="$emit('update',m.id,{selectedTarget:null,status:'rejected'})">拒绝</button></div></td></tr></tbody></table></div></template>
